        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    maxPossibleScore: 104,
                    currentR2: 0,
                    scoreHistory: [],
                    r2History: [],
                    scenarioScores: [0, 0, 0, 0],
                    lastFeedback: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    specChoice: 1,
                    diagChoice: 1
                };
            }
            this._updateBriefing(state);
        }

        // On screen the option values are period codes such as spec_r3_2 and diag_r3_4 instead of the bare
        // 1 to 4, so the EQIL guard shuffles both lists per game (it keeps all-numeric lists in their original
        // order, and the full-credit diagnostic was always the last one). Decisions and scoring keep the bare
        // number. The code format also sets the fixed order of the Open player (no game id): with it no fixed
        // pair of positions scores more than 66 of the 104 points.
        _optVal(code) {
            var s = String(code === undefined || code === null ? '' : code);
            var k = s.lastIndexOf('_');
            return k >= 0 ? s.slice(k + 1) : s;
        }

        validateDecisions(decisions) {
            var specEl = document.getElementById('specSelect');
            var diagEl = document.getElementById('diagSelect');
            if (specEl) decisions.specChoice = parseInt(this._optVal(specEl.value));
            if (diagEl) decisions.diagChoice = parseInt(this._optVal(diagEl.value));

            if (!decisions.specChoice || decisions.specChoice < 1 || decisions.specChoice > 4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('spec_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.diagChoice || decisions.diagChoice < 1 || decisions.diagChoice > 4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('diag_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            // Undo + resubmit idempotency guard (see EQIL undo pattern): roll domainState
            // back to its pre-phase snapshot before re-applying so cumulative fields
            // (totalScore/scoreHistory/r2History/scenarioScores) are never double-counted.
            var _period = state.currentPeriod || 1;
            if (!this._periodSnapshots) this._periodSnapshots = {};
            if (this._periodSnapshots[_period]) {
                var _restored = JSON.parse(this._periodSnapshots[_period]);
                var _k;
                for (_k in state.domainState) { delete state.domainState[_k]; }
                for (_k in _restored) { state.domainState[_k] = _restored[_k]; }
                for (var _p in this._periodSnapshots) { if (Number(_p) > _period) delete this._periodSnapshots[_p]; }
            }
            this._periodSnapshots[_period] = JSON.stringify(state.domainState);
            var d = state.decisions;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var specOption = round.specOptions.find(function(o) { return o.value === d.specChoice; });
            var diagOption = round.diagOptions.find(function(o) { return o.value === d.diagChoice; });

            var specScore = specOption ? specOption.score : 0;
            var diagScore = diagOption ? diagOption.score : 0;
            var periodScore = specScore + diagScore;
            var r2 = specOption ? specOption.r2 : 0;

            state.domainState.totalScore += periodScore;
            state.domainState.currentR2 = r2;
            state.domainState.scoreHistory.push(periodScore);
            state.domainState.r2History.push(r2);

            var scenarioIdx = round.scenario - 1;
            state.domainState.scenarioScores[scenarioIdx] += periodScore;

            var lang = this._lang();
            var fb = (lang === 'es') ? round.feedbackEs : round.feedback;
            state.domainState.lastFeedback = fb;

            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (feedbackPanel && feedbackText) {
                feedbackPanel.style.display = 'block';
                feedbackText.innerHTML = fb;
            }

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            // Persist graded performance (0-100 percentage) for server reporting.
            var _pct = Math.max(0, Math.min(100, Math.round((state.domainState.totalScore /
                       (state.domainState.maxPossibleScore || 104)) * 100)));
            var _tier = 'needs';
            if (_pct >= 80) _tier = 'excellent';
            else if (_pct >= 60) _tier = 'competent';
            else if (_pct >= 40) _tier = 'developing';
            state.domainState.performance = {
                overallScore: _pct,
                totalScore: state.domainState.totalScore,
                maxScore: state.domainState.maxPossibleScore || 104,
                performanceTier: _tier
            };

            return {
                period: state.currentPeriod,
                scenario: round.scenarioName,
                phase: round.phase,
                specScore: specScore,
                diagScore: diagScore,
                periodScore: periodScore,
                r2: r2,
                totalScore: state.domainState.totalScore
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore',
                function(v) { return Math.round(v) + ' / 104'; });
            uiManager.bind('r2Display', 'domainState.currentR2',
                function(v) { return v > 0 ? v.toFixed(2) : '\u2014'; });

            // Repaint the round texts in the new language when the player switches language (bound once).
            if (!this._langWired) {
                this._langWired = true;
                var self = this;
                var relabel = function() { try { self._relabel(); } catch (e) {} };
                document.addEventListener('express:langchanged', relabel);
                var sim = window.mySimulation;
                if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                    sim.eventBus.on('language:changed', relabel);
                }
            }
        }

