        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) {
                return 'P' + (i + 1);
            });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.scoreHistory },
                        { data: state.domainState.r2History }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            if (!history.length) {
                return { totalScore: 0, maxScore: 104, percentage: 0, overallScore: 0,
                         performanceTier: 'needs', performanceLabel: t('tier_needs'),
                         performance: t('tier_needs'), insights: [] };
            }
            var scores = history.map(function(r) { return r.results ? r.results.periodScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, p) { return s + p; }, 0);
            var maxScore = 104;
            var pct = Math.max(0, Math.min(100, Math.round((totalScore / maxScore) * 100)));

            var tier = 'needs';
            if (pct >= 80) tier = 'excellent';
            else if (pct >= 60) tier = 'competent';
            else if (pct >= 40) tier = 'developing';

            var insights = [];
            if (pct >= 80) insights.push(t('insight_high'));
            else if (pct >= 60) insights.push(t('insight_mid'));
            else if (pct >= 40) insights.push(t('insight_dev'));
            else insights.push(t('insight_low'));

            return {
                totalScore: totalScore,
                maxScore: maxScore,
                percentage: pct,
                overallScore: pct,
                performanceTier: tier,
                performanceLabel: t('tier_' + tier),
                performance: t('tier_' + tier),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            summary = summary || {};
            var pct = (summary.percentage != null) ? summary.percentage : (summary.overallScore || 0);
            var total = (summary.totalScore != null) ? summary.totalScore : 0;
            var max = summary.maxScore || 104;
            var label = summary.performanceLabel || t('tier_' + (summary.performanceTier || 'needs'));
            var insights = summary.insights || [];
            var html = '<div class="regressionlab-completion">';
            html += '<h3 class="regressionlab-completion-title">' + t('results_title') + '</h3>';
            html += '<div class="regressionlab-completion-tier">' + t('results_tier_label') + ': <strong>' + label + '</strong></div>';
            html += '<div class="regressionlab-completion-stats">';
            html += '<span>' + t('results_score_label') + ': <strong>' + total + '/' + max + '</strong></span>';
            html += '<span>' + t('results_pct_label') + ': <strong>' + pct + '%</strong></span>';
            html += '</div>';
            if (insights.length) {
                html += '<ul class="regressionlab-completion-insights">';
                for (var i = 0; i < insights.length; i++) html += '<li>' + insights[i] + '</li>';
                html += '</ul>';
            }
            html += '</div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.periodScore <= 4) {
                return window.mySimulation.t('hint_low_score');
            }
            if (results.periodScore >= 11) {
                return window.mySimulation.t('hint_high_score');
            }
            if (results.diagScore === 0) {
                return window.mySimulation.t('hint_no_diag');
            }
            return null;
        }

