                { key: 'results.r2', label: 'R\u00b2', i18nKey: 'col_r2', formatter: function(v) { return v ? v.toFixed(2) : '\u2014'; } },
                { key: 'results.specScore', label: 'Spec Score', i18nKey: 'col_spec_score' },
