        // Active language: the platform runtime exposes currentLanguage, the Open player exposes lang.
        _lang() {
            var sim = window.mySimulation || {};
            var l = sim.currentLanguage || sim.lang || document.documentElement.lang || 'en';
            return String(l).toLowerCase().slice(0, 2);
        }

        _t(key) {
            var sim = window.mySimulation;
            if (sim && typeof sim.t === 'function') { return sim.t(key); }
            var en = this.getTranslations().en;
            return (en[key] != null) ? en[key] : key;
        }

        // History cells store the English scenario name and the phase id; show them in the active language.
        _scenarioLabel(v) {
            if (this._lang() !== 'es') { return v; }
            var r = this.ROUNDS.find(function(x) { return x.scenarioName === v; });
            return r ? r.scenarioNameEs : v;
        }

        _phaseLabel(v) {
            if (this._lang() !== 'es') { return v; }
            var r = this.ROUNDS.find(function(x) { return x.phase === v; });
            return r ? r.phaseEs : v;
        }

        // Same texts _updateBriefing paints, refreshed in place so the player keeps the current selections.
        _relabel() {
            var st = (window.mySimulation && window.mySimulation.state) || {};
            var idx = Math.min((st.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var es = this._lang() === 'es';
            var el = document.getElementById('briefingText');
            if (el) { el.innerHTML = es ? round.briefingEs : round.briefing; }
            el = document.getElementById('phaseDisplay');
            if (el) { el.textContent = es ? round.phaseEs : (round.phase === 'build' ? 'Build' : 'Diagnose'); }
            el = document.getElementById('specLabelEl');
            if (el) { el.textContent = es ? round.specLabelEs : round.specLabel; }
            el = document.getElementById('diagLabelEl');
            if (el) { el.textContent = es ? round.diagLabelEs : round.diagLabel; }
            var pairs = [['specSelect', round.specOptions], ['diagSelect', round.diagOptions]];
            for (var i = 0; i < pairs.length; i++) {
                var sel = document.getElementById(pairs[i][0]);
                if (!sel) { continue; }
                for (var j = 0; j < sel.options.length; j++) {
                    var val = this._optVal(sel.options[j].value);
                    var src = pairs[i][1].find(function(x) { return String(x.value) === val; });
                    if (src) { sel.options[j].textContent = es ? src.textEs : src.text; }
                }
            }
            var prev = (st.currentPeriod || 1) - 2;
            var fbEl = document.getElementById('feedbackText');
            if (fbEl && prev >= 0 && fbEl.innerHTML) {
                var pr = this.ROUNDS[Math.min(prev, this.ROUNDS.length - 1)];
                fbEl.innerHTML = es ? pr.feedbackEs : pr.feedback;
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = this._lang();

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = (lang === 'es') ? round.briefingEs : round.briefing;
            }

            var scenarioEl = document.getElementById('scenarioDisplay');
            if (scenarioEl) {
                scenarioEl.textContent = round.scenario + ' / 4';
            }

            var phaseEl = document.getElementById('phaseDisplay');
            if (phaseEl) {
                if (lang === 'es') {
                    phaseEl.textContent = round.phaseEs;
                } else {
                    phaseEl.textContent = round.phase === 'build' ? 'Build' : 'Diagnose';
                }
            }

            var specSelect = document.getElementById('specSelect');
            if (specSelect) {
                specSelect.innerHTML = '';
                var specOpts = round.specOptions;
                for (var i = 0; i < specOpts.length; i++) {
                    var opt = document.createElement('option');
                    opt.value = 'spec_r' + (idx + 1) + '_' + specOpts[i].value;
                    opt.textContent = (lang === 'es') ? specOpts[i].textEs : specOpts[i].text;
                    specSelect.appendChild(opt);
                }
            }

            var diagSelect = document.getElementById('diagSelect');
            if (diagSelect) {
                diagSelect.innerHTML = '';
                var diagOpts = round.diagOptions;
                for (var j = 0; j < diagOpts.length; j++) {
                    var dopt = document.createElement('option');
                    dopt.value = 'diag_r' + (idx + 1) + '_' + diagOpts[j].value;
                    dopt.textContent = (lang === 'es') ? diagOpts[j].textEs : diagOpts[j].text;
                    diagSelect.appendChild(dopt);
                }
            }

            var specLabelEl = document.getElementById('specLabelEl');
            if (specLabelEl) {
                specLabelEl.textContent = (lang === 'es') ? round.specLabelEs : round.specLabel;
            }

            var diagLabelEl = document.getElementById('diagLabelEl');
            if (diagLabelEl) {
                diagLabelEl.textContent = (lang === 'es') ? round.diagLabelEs : round.diagLabel;
            }

            var feedbackPanel = document.getElementById('feedbackPanel');
            if (feedbackPanel && state.currentPeriod && state.currentPeriod <= 1) {
                feedbackPanel.style.display = 'none';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new RegressionLabAdapter(), {
            simulationType: 'regression_lab',
            maxPeriods: 8,
            autoSaveInterval: 30000
        });
    });

})();
